"""
Tools module for codx-junior API.

This module aggregates all available tools for chat and project interactions.
Tools are organized as callable functions with associated metadata for
integration with language models and the API.

Tool Scope Levels:
    - "global": Tools always included in conversations (e.g., code_block_generator)
    - "chat": Tools available based on conversation context and selection
    - "profile": Tools available based on user profile or role

Tool Response Types:
    - str: Traditional single-string response (used for LLM context)
    - ToolResponse: Dual-return object for tools that need to produce both
                    user-facing content and LLM feedback

Dual-Response Tool Flow:
    Tools returning ToolResponse objects enable a sophisticated pattern:

    1. **Execution**: Tool runs and returns ToolResponse(user_content, llm_feedback)

    2. **Separation of concerns**:
       - user_content: Formatted output (e.g., code blocks) for the chat UI
       - llm_feedback: Lightweight feedback for model context

    3. **Integration**:
       - user_content is accumulated and merged into the final assistant message
       - llm_feedback is sent to the model in a tool message for context

    4. **Final Message**:
       content = LLM streamed text + accumulated user_content from all tools

    This pattern ensures:
    - Users see rich formatted output from tools
    - Model receives focused feedback without bloated context
    - No information loss during multi-step tool execution

Example: code_block_generator Tool
    Input: Generate a formatted Python function
    Returns ToolResponse with:
        - user_content: "```python\ndef hello():\n    return 'world'\n```"
        - llm_feedback: "Generated 50-char function successfully"

    Flow:
        - user_content → accumulated for final message
        - llm_feedback → sent to model in tool message
        - Final message = LLM text + formatted code block

Made with ❤️ by codx-junior
"""

import logging
from typing import Optional, Dict, Union

# Import tools
from .fetch_webpage import fetch_webpage
from .project_tools import project_search, project_read_file, project_write_file
from .code_writer import code_writer
from .code_block_generator import code_block_generator
from .model import ToolResponse

# Configure logging
logger = logging.getLogger(__name__)


def test_tool() -> str:
    """Test tool for debugging purposes.

    Returns:
        str: A simple test message.

    Made with ❤️ by codx-junior
    """
    return "test ok!"


# Define TOOLS
TOOLS = [
    {
        "tool_json": {
            "type": "function",
            "function": {
                "name": "fetch_webpage",
                "description": "Fetch a webpage and convert it to markdown format.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "url": {
                            "type": "string",
                            "description": "The URL of the webpage to fetch"
                        },
                        "include_images": {
                            "type": "boolean",
                            "description": "Whether to include image references in the markdown"
                        },
                        "max_length": {
                            "type": "integer",
                            "description": "Maximum length of the output markdown"
                        },
                        "headers": {
                            "type": "object",
                            "description": "Optional HTTP headers for the request"
                        }
                    },
                    "required": ["url"]
                }
            }
        },
        "settings": {"async": False, "scope": "chat"},
        "tool_call": fetch_webpage
    },
    {
        "tool_json": {
            "type": "function",
            "function": {
                "name": "project_search",
                "description": "Search for documents within a project using the provided search string.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "search": {
                            "type": "string",
                            "description": "The search query string used to find relevant documents."
                        },
                        "validation": {
                            "type": "string",
                            "description": "An optional brief text used to validate the content found by the search. This text will help reducing large documents and extracting only important content. "
                        }
                    },
                    "required": ["search"]
                }
            }
        },
        "settings": {"async": False, "project_settings": True, "scope": "chat"},
        "tool_call": project_search
    },
    {
        "tool_json": {
            "type": "function",
            "function": {
                "name": "project_read_file",
                "description": "Allows to read project's file content from a relative or absolute file path",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "file_path": {
                            "type": "string",
                            "description": "Relative or absolute path to the file to read."
                        }
                    },
                    "required": ["file_path"]
                }
            }
        },
        "settings": {"async": False, "project_settings": True, "scope": "chat"},
        "tool_call": project_read_file
    },
    {
        "tool_json": {
            "type": "function",
            "function": {
                "name": "code_block_generator",
                "description": "Format a code block with language, file path, and content into markdown code block format.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "language": {
                            "type": "string",
                            "description": "The programming language or code block type (python, javascript, html, markdown, etc.)"
                        },
                        "file_path": {
                            "type": "string",
                            "description": "The target file path for the code block"
                        },
                        "content": {
                            "type": "string",
                            "description": "The actual code or file content"
                        }
                    },
                    "required": ["language", "file_path", "content"]
                }
            }
        },
        "settings": {
            "async": False,
            "scope": "global",
            "dual_response": True,
        },
        "tool_call": code_block_generator
    }
]

